import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import AnimatedPopup from '../components/AnimatedPopup';
import './WalletPage.css'; // Added CSS file for wallet styling

const WalletPage = () => {
  const { user } = useAuth();
  const [showWalletModal, setShowWalletModal] = useState(false);
  const [balance, setBalance] = useState(0);
  const [inventory, setInventory] = useState([]);
  const [activeTab, setActiveTab] = useState('deposit'); // 'deposit' or 'withdraw'
  const [amount, setAmount] = useState('');
  const [address, setAddress] = useState('');
  const [showPopup, setShowPopup] = useState(false);
  const [popupMessage, setPopupMessage] = useState('');
  const [popupType, setPopupType] = useState('info');

  useEffect(() => {
    if (user) {
      // In a real app, this would come from an API call
      setBalance(user.balance || 0);

      // Fetch inventory from API
      fetchInventory();
    }
  }, [user]);

  const fetchInventory = async () => {
    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/users/inventory/${user.id}`, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });
      const data = await response.json();
      setInventory(data.items || []);
    } catch (error) {
      console.error('Error fetching inventory:', error);
      // Use mock data as fallback
      setInventory([
        { id: 1, name: 'Golden Coin', value: 100, rarity: 'rare', image: '/images/gold-coin.png' },
        { id: 2, name: 'Silver Token', value: 50, rarity: 'uncommon', image: '/images/silver-token.png' },
        { id: 3, name: 'Diamond Gem', value: 500, rarity: 'epic', image: '/images/diamond-gem.png' },
        { id: 4, name: 'Ruby Jewel', value: 250, rarity: 'legendary', image: '/images/ruby-jewel.png' },
      ]);
    }
  };

  const showCustomPopup = (message, type = 'info') => {
    setPopupMessage(message);
    setPopupType(type);
    setShowPopup(true);

    // Auto-hide after 3 seconds
    setTimeout(() => {
      setShowPopup(false);
    }, 3000);
  };

  const handleDeposit = async () => {
    if (!amount || parseFloat(amount) <= 0) {
      showCustomPopup('Please enter a valid amount', 'error');
      return;
    }

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/wallet/deposit`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({
          amount: parseFloat(amount)
        })
      });

      const result = await response.json();

      if (response.ok) {
        showCustomPopup('Deposit request submitted successfully!', 'success');
        setAmount('');
        // Update balance
        setBalance(prev => prev + parseFloat(amount));
      } else {
        showCustomPopup(result.message || 'Failed to submit deposit', 'error');
      }
    } catch (error) {
      showCustomPopup('Error submitting deposit request', 'error');
    }
  };

  const handleWithdraw = async () => {
    if (!amount || !address || parseFloat(amount) <= 0) {
      showCustomPopup('Please enter a valid amount and address', 'error');
      return;
    }

    if (parseFloat(amount) > balance) {
      showCustomPopup('Insufficient balance for withdrawal', 'error');
      return;
    }

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/wallet/withdraw`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({
          amount: parseFloat(amount),
          address
        })
      });

      const result = await response.json();

      if (response.ok) {
        showCustomPopup('Withdrawal request submitted successfully!', 'success');
        setAmount('');
        setAddress('');
        // Update balance
        setBalance(prev => prev - parseFloat(amount));
      } else {
        showCustomPopup(result.message || 'Failed to submit withdrawal', 'error');
      }
    } catch (error) {
      showCustomPopup('Error submitting withdrawal request', 'error');
    }
  };

  const getRarityClass = (rarity) => {
    switch(rarity) {
      case 'common': return 'rarity-common';
      case 'uncommon': return 'rarity-uncommon';
      case 'rare': return 'rarity-rare';
      case 'epic': return 'rarity-epic';
      case 'legendary': return 'rarity-legendary';
      case 'mythic': return 'rarity-mythic';
      default: return 'rarity-common';
    }
  };

  return (
    <div className="wallet-page">
      <div className="page-header">
        <h1>Your Wallet</h1>
        <p>Manage your AMP coins and items</p>
      </div>

      <div className="wallet-overview">
        <div className="balance-card enhanced">
          <div className="balance-info">
            <h2>Your Balance</h2>
            <p className="balance-amount">{balance?.toLocaleString()} AMP</p>
          </div>
          <button 
            className="btn btn-primary wallet-open-btn"
            onClick={() => setShowWalletModal(true)}
          >
            Open Wallet
          </button>
        </div>
      </div>

      {/* Wallet Modal */}
      {showWalletModal && (
        <div className="wallet-modal-overlay" onClick={() => setShowWalletModal(false)}>
          <div className="wallet-modal enhanced" onClick={(e) => e.stopPropagation()}>
            {/* Modal header with deposit/withdraw buttons */}
            <div className="wallet-modal-header">
              <div className="modal-title-section">
                <h2>Wallet Management</h2>
                <p className="modal-balance">Current Balance: <span className="balance-highlight">{balance?.toLocaleString()} AMP</span></p>
              </div>
              <div className="wallet-actions">
                <button 
                  className={`modal-action-btn ${activeTab === 'deposit' ? 'active' : ''}`}
                  onClick={(e) => {
                    e.stopPropagation();
                    setActiveTab('deposit');
                  }}
                >
                  Deposit
                </button>
                <button 
                  className={`modal-action-btn ${activeTab === 'withdraw' ? 'active' : ''}`}
                  onClick={(e) => {
                    e.stopPropagation();
                    setActiveTab('withdraw');
                  }}
                >
                  Withdraw
                </button>
                <button 
                  className="modal-close-btn"
                  onClick={() => setShowWalletModal(false)}
                >
                  ×
                </button>
              </div>
            </div>

            {/* Modal content */}
            <div className="wallet-modal-content">
              {/* Inventory Section */}
              <div className="inventory-section">
                <div className="section-header">
                  <h3>Your Items</h3>
                  <span className="items-count">{inventory.length} items</span>
                </div>
                <div className="inventory-grid enhanced">
                  {inventory.length > 0 ? (
                    inventory.map((item) => (
                      <div key={item.id || item.itemId} className="inventory-item enhanced">
                        <div className="item-image-container">
                          {item.details?.imageUrl || item.image ? (
                            <img 
                              src={item.details?.imageUrl || item.image} 
                              alt={item.details?.name || item.name} 
                              className="item-image"
                              onError={(e) => {
                                e.target.src = '/default-item.png';
                                e.target.classList.add('default-image');
                              }}
                            />
                          ) : (
                            <div className="default-item-icon">💎</div>
                          )}
                        </div>
                        <div className="item-details">
                          <h4 className="item-name">{item.details?.name || item.name}</h4>
                          <p className="item-value">{(item.value || item.details?.value)?.toLocaleString()} AMP</p>
                          <span className={`badge ${getRarityClass(item.details?.rarity || item.rarity)}`}>
                            {item.details?.rarity || item.rarity}
                          </span>
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="no-items-placeholder">
                      <div className="empty-icon">🎒</div>
                      <p className="no-items-text">No items in your inventory</p>
                      <p className="no-items-subtext">Start playing games to earn items!</p>
                    </div>
                  )}
                </div>
              </div>

              {/* Transaction Form Section */}
              <div className="transaction-section">
                <h3>{activeTab === 'deposit' ? 'Deposit Funds' : 'Withdraw Funds'}</h3>

                {activeTab === 'deposit' ? (
                  <div className="transaction-form deposit-form">
                    <div className="form-group">
                      <label>Amount (AMP)</label>
                      <input
                        type="number"
                        value={amount}
                        onChange={(e) => setAmount(e.target.value)}
                        placeholder="Enter amount to deposit"
                        className="form-control enhanced"
                        min="0"
                      />
                    </div>
                    <div className="form-group">
                      <label>Deposit Address</label>
                      <input
                        type="text"
                        value={address}
                        onChange={(e) => setAddress(e.target.value)}
                        placeholder="Your deposit address"
                        className="form-control enhanced"
                        readOnly
                      />
                      <small className="form-text">Send AMP coins to this address to deposit</small>
                    </div>
                    <div className="form-actions">
                      <button 
                        className="btn btn-cancel"
                        onClick={() => setShowWalletModal(false)}
                      >
                        Cancel
                      </button>
                      <button 
                        className="btn btn-success"
                        onClick={handleDeposit}
                      >
                        Confirm Deposit
                      </button>
                    </div>
                  </div>
                ) : (
                  <div className="transaction-form withdraw-form">
                    <div className="form-group">
                      <label>Amount (AMP)</label>
                      <input
                        type="number"
                        value={amount}
                        onChange={(e) => setAmount(e.target.value)}
                        placeholder="Enter amount to withdraw"
                        className="form-control enhanced"
                        min="0"
                        max={balance}
                      />
                      <small className="form-text">Available: {balance?.toLocaleString()} AMP</small>
                    </div>
                    <div className="form-group">
                      <label>Withdrawal Address</label>
                      <input
                        type="text"
                        value={address}
                        onChange={(e) => setAddress(e.target.value)}
                        placeholder="Enter your wallet address"
                        className="form-control enhanced"
                      />
                    </div>
                    <div className="form-actions">
                      <button 
                        className="btn btn-cancel"
                        onClick={() => setShowWalletModal(false)}
                      >
                        Cancel
                      </button>
                      <button 
                        className="btn btn-danger"
                        onClick={handleWithdraw}
                      >
                        Confirm Withdrawal
                      </button>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Custom animated popup */}
      {showPopup && (
        <AnimatedPopup 
          message={popupMessage} 
          type={popupType} 
          onClose={() => setShowPopup(false)}
        />
      )}
    </div>
  );
};

export default WalletPage;
